n secondary action-link" href="index.php?page=assets&id=<?= (int)$a['id'] ?>">Aç</a></td></tr><?php endforeach; ?><?php if(!$assets): ?><tr><td colspan="7">Demirbaş kaydı yok.</td></tr><?php endif; ?></tbody></table></div></section></div><?php endif; ?>
